using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice;

internal sealed class LatticeBRSTRelativeZeroModeDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string prose, string telescope, DescribeRole role) => Describe.Lean(
        DescribeId.Create("latticebrstrelativezeromode-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/LatticeBRSTRelativeZeroMode." + name),
        H(name), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(prose)), Paragraph(Text("Exact source telescope: " + telescope))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original relative BRST zero modes and literal shell stability",
        H("Original relative BRST zero modes and literal shell stability"), Blocks(
            Paragraph(Text("All states belong to the original all-charge lattice matter tensor ghost carrier. The lattice has arbitrary integral symmetric even Gram matrix and arbitrary natural rank, including zero. All mode sums range over the integers and are finite only after application to each state. There is no hidden finite cutoff, vacuum change or intercept shift. H is arbitrary unless both H*gramComplex D=1 and gramComplex D*H=1 are explicitly displayed.")),
            Paragraph(Text("The existing native LatticeRelativeMassShell.totalCharge_mem_fixedMomentum and totalCharge_mem_relativeMassShell already prove preservation by the original Q. Together with equality of Qhat and Q on the literal relative domain, these laws give its momentum component. The finite row/column/diagonal decomposition identifies the zero-mode-free action needed for a later HPL bridge.")),
            Node("State", "The unchanged carrier is the original lattice matter Carrier D tensored with the original algebraic ghost occupation Fock space.", "abbrev State (D : LatticeData)", DescribeRole.Definition),
            Node("L0", "This is the actual unshifted matterMode D H 0 plus ghostVirasoro D 0.", "abbrev L0 (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("cubicZeroFree", "The original cubicTerm is summed after application to v. The integer pair survives exactly when p, q and p+q are nonzero. Local finite support proves linearity; no endomorphism-valued infinite sum is used.", "def cubicZeroFree : Module.End ℂ Fock", DescribeRole.Definition),
            Node("matterZeroFree", "The original finite-on-each-state matter summation has only its m=0 summand removed. Negative modes and zero lattice charge remain in scope.", "def matterZeroFree (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("ghostZeroFree", "This is identity on the unchanged matter carrier tensored with cubicZeroFree.", "def ghostZeroFree (D : LatticeData) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("zeroModeFreeCharge", "The finite matter tail plus the lifted finite cubic tail, with the original coefficients and normal ordering.", "def zeroModeFreeCharge (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("ghost_b_zero_square", "The actual zero b mode squares to zero by the original all-integer CAR, transported through the tensor lift. It gives the b projection and the Qhat anticommutator.", "theorem ghost_b_zero_square (D : LatticeData) : ghostB D 0 * ghostB D 0 = 0", DescribeRole.Theorem),
            Node("ghost_c_zero_square", "The actual zero c mode squares to zero by the original CAR. It shows that the c projection maps into ker c0.", "theorem ghost_c_zero_square (D : LatticeData) : ghostC D 0 * ghostC D 0 = 0", DescribeRole.Theorem),
            Node("ghost_zero_mixed", "The original tensor b0 and c0 have anticommutator identity. This gives both kernel-fixing laws and the direct decomposition.", "theorem ghost_zero_mixed (D : LatticeData) : ghostB D 0 * ghostC D 0 + ghostC D 0 * ghostB D 0 = (1 : Module.End ℂ (State D))", DescribeRole.Theorem),
            Node("bZeroProjector", "The actual ordered product b0*c0; it is a projection onto ker b0, not an assumed projector.", "def bZeroProjector (D : LatticeData) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("cZeroProjector", "The actual ordered product c0*b0; it is a projection onto ker c0.", "def cZeroProjector (D : LatticeData) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("ghostB_bZeroProjector", "The b0 image of the literal b0*c0 product vanishes. Thus the product maps into the stated kernel.", "theorem ghostB_bZeroProjector (D : LatticeData) : ghostB D 0 * bZeroProjector D = 0", DescribeRole.Theorem),
            Node("ghostC_cZeroProjector", "The c0 image of the literal c0*b0 product vanishes. Thus the product maps into the stated kernel.", "theorem ghostC_cZeroProjector (D : LatticeData) : ghostC D 0 * cZeroProjector D = 0", DescribeRole.Theorem),
            Node("bZeroProjector_fix_of_ker", "The literal b0*c0 product fixes every vector annihilated by b0. This is the kernel-fixing field of the native projection.", "theorem bZeroProjector_fix_of_ker (D : LatticeData) (x : State D) (hx : ghostB D 0 x = 0) : bZeroProjector D x = x", DescribeRole.Theorem),
            Node("cZeroProjector_fix_of_ker", "The literal c0*b0 product fixes every vector annihilated by c0.", "theorem cZeroProjector_fix_of_ker (D : LatticeData) (x : State D) (hx : ghostC D 0 x = 0) : cZeroProjector D x = x", DescribeRole.Theorem),
            Node("bZeroProjector_isProj", "The actual product maps every state into ker b0 and fixes that kernel. Mathlib LinearMap.IsProj.isIdempotentElem supplies its idempotence directly, without another wrapper theorem. Its codomain restriction is one coordinate of the direct decomposition.", "theorem bZeroProjector_isProj (D : LatticeData) : LinearMap.IsProj (LinearMap.ker (ghostB D 0)) (bZeroProjector D)", DescribeRole.Theorem),
            Node("cZeroProjector_isProj", "The actual product maps every state into ker c0 and fixes that kernel; its idempotence follows from the same native projection interface. Its codomain restriction is the other coordinate of the direct decomposition.", "theorem cZeroProjector_isProj (D : LatticeData) : LinearMap.IsProj (LinearMap.ker (ghostC D 0)) (cZeroProjector D)", DescribeRole.Theorem),
            Node("zeroModeDecomposition", "A linear equivalence sends x to (b0*c0*x,c0*b0*x) in ker b0 times ker c0; its inverse adds the two original states. The original CAR proves both inverse laws. This is a native splitting of the original space, not a replacement carrier.", "def zeroModeDecomposition (D : LatticeData) : State D ≃ₗ[ℂ] (LinearMap.ker (ghostB D 0) × LinearMap.ker (ghostC D 0))", DescribeRole.Definition),
            Node("totalL0_b_zero", "The original total zero mode commutes with b0 for arbitrary H. The matter and ghost factors commute separately; ghost Ward at (0,0) has zero coefficient.", "theorem totalL0_b_zero (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : L0 D H * ghostB D 0 - ghostB D 0 * L0 D H = 0", DescribeRole.Theorem),
            Node("Qhat", "Exactly totalCharge D H minus c0*L0 minus b0*R0, using the original totalCharge=T+id tensor Qg and the original R0. This definition does not postulate decomposition or stability.", "def Qhat (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Module.End ℂ (State D)", DescribeRole.Definition),
            Node("Qhat_b_zero", "The actual b0 anticommutator of Qhat vanishes. The total b Ward law, zero CAR and the ordinary even R0-b0 commutator prove cancellation.", "theorem Qhat_b_zero (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Qhat D H * ghostB D 0 + ghostB D 0 * Qhat D H = 0", DescribeRole.Theorem),
            Node("ghost_zero_split", "The original statewise finite ordered-pair cubic sum splits into c0*Lg0 plus b0*R0 plus the zero-free tail. The proof partitions the zero row and column with their zero overlap, the remaining p+q=0 diagonal, and the tail. Both normal-order branches and every integer pair remain included.", "theorem ghost_zero_split (v : Fock) : BcGhostBRST.Qg v = c 0 (BcGhostVirasoro.L 0 v) + b 0 (BcGhostBRST.R 0 v) + cubicZeroFree v", DescribeRole.Theorem),
            Node("matter_zero_split", "The actual m=0 matter summand is matterMode D H 0 times c0. Its complement is the original matterZeroFree sum; no inverse-Gram condition is required.", "theorem matter_zero_split (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (x : State D) : T D H x = (matterMode D H 0 * ghostC D 0) x + matterZeroFree D H x", DescribeRole.Theorem),
            Node("original_charge_split", "For every original state, Qx=c0*L0*x+b0*R0*x+zeroModeFreeCharge*x. Tensor induction lifts the ghost identity, and commutation of the two tensor factors combines the matter zero mode.", "theorem original_charge_split (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (x : State D) : totalCharge D H x = ghostC D 0 (L0 D H x) + ghostB D 0 (ghostR D 0 x) + zeroModeFreeCharge D H x", DescribeRole.Theorem),
            Node("Qhat_eq_zeroModeFree", "On the entire unchanged carrier, Qhat equals the explicitly defined statewise finite zero-mode-free charge. No shell or inverse-Gram hypothesis is used.", "theorem Qhat_eq_zeroModeFree (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) : Qhat D H = zeroModeFreeCharge D H", DescribeRole.Theorem),
            Node("Qhat_eq_original_on_relative_shell", "Qhat x equals Q x when the actual b0 x and unshifted totalL0 x vanish. The even ordinary R0-b0 commutator is required to eliminate b0*R0*x. No global equality Qhat=Q is asserted.", "theorem Qhat_eq_original_on_relative_shell (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (x : State D) (hb : ghostB D 0 x = 0) (hL : L0 D H x = 0) : Qhat D H x = totalCharge D H x", DescribeRole.Theorem),
            Node("Qhat_totalL0_comm", "The two original inverse-Gram identities imply commutation of Qhat with the actual total L0. At r=0 the native rank-dependent anomaly vanishes for every rank. The separate R0 covariance uses no inverse-Gram premise.", "theorem Qhat_totalL0_comm (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (hHG : H * LatticeSugawaraCurrents.gramComplex D = 1) (hGH : LatticeSugawaraCurrents.gramComplex D * H = 1) : L0 D H * Qhat D H - Qhat D H * L0 D H = 0", DescribeRole.Theorem),
            Node("Qhat_preserves_b0_kernel", "Applying the actual Qhat-b0 anticommutator proves preservation of the literal b0 kernel; this supplies the b0 part of shell preservation.", "theorem Qhat_preserves_b0_kernel (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (x : State D) (hx : ghostB D 0 x = 0) : ghostB D 0 (Qhat D H x) = 0", DescribeRole.Theorem),
            Node("Qhat_preserves_L0_kernel", "Under both original inverse-Gram identities, the actual Qhat preserves ker of the unshifted total L0. This supplies the L0 part of shell preservation.", "theorem Qhat_preserves_L0_kernel (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (hHG : H * LatticeSugawaraCurrents.gramComplex D = 1) (hGH : LatticeSugawaraCurrents.gramComplex D * H = 1) (x : State D) (hx : L0 D H x = 0) : L0 D H (Qhat D H x) = 0", DescribeRole.Theorem),
            Node("Qhat_preserves_relativeMassShell", "For every original fixed charge a, including zero, the actual Qhat preserves the literal intersection (fixedMomentum D a intersect ker b0) intersect ker totalL0. Momentum preservation reuses LatticeRelativeMassShell.totalCharge_mem_fixedMomentum and equality with the original Q on this domain. The two kernel laws complete the proof; no stability certificate or nilpotence premise is assumed.", "theorem Qhat_preserves_relativeMassShell (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (hHG : H * LatticeSugawaraCurrents.gramComplex D = 1) (hGH : LatticeSugawaraCurrents.gramComplex D * H = 1) (a : Charge D) (x : State D) (hx : x ∈ LatticeRelativeMassShell.relativeMassShell D H a) : Qhat D H x ∈ LatticeRelativeMassShell.relativeMassShell D H a", DescribeRole.Theorem),
            Node("relativeQhat", "The genuine linear endomorphism of the original relativeMassShell restricts the explicit finite zeroModeFreeCharge. The proved equality with Qhat transports its preservation law. Its ambient action equals Qhat x and the original Q x on this literal shell; nilpotence is not built into this endomorphism.", "def relativeQhat (D : LatticeData) (H : Matrix (Fin D.rank) (Fin D.rank) ℂ) (hHG : H * LatticeSugawaraCurrents.gramComplex D = 1) (hGH : LatticeSugawaraCurrents.gramComplex D * H = 1) (a : Charge D) : Module.End ℂ (LatticeRelativeMassShell.relativeMassShell D H a)", DescribeRole.Definition),
            Paragraph(Text("These are repository-derived algebraic results; no literature novelty is claimed. Nilpotence, strict raising and energy estimates, HPL hypotheses and construction, BRST cohomology, no-ghost, full Monster moonshine, VOA/CFT, anomaly fusion, physical strings and AdS/CFT remain separate unfinished work. A supplier identity alone proves none of those completions.")))));
}
